import faults from "./data/fault-bed.json";
import data from "./data/ledger.json";
import type { RunLine } from "./runlog";

/**
 * The robot's "done" across every live night, from the evidence ledger (jury round 3, item C2).
 * `data/ledger.json` is generated by `scripts/ledger.py` from the live run logs, next to
 * docs/runs/ledger.csv; nothing here is typed in by hand. A night counts when its log was found and
 * the robot reported at least one "done" in it. Board tests (seed-specific board experiments, not
 * builds: `kind: "board-test"`) are in the file only when complete, so they count across all nights,
 * never in a build's figure: their commit is the checkout's HEAD, not what played (scripts/ledger.py).
 */

export type LedgerNight = {
  shift: string;
  started: string;
  seed: number | null;
  commit: string;
  /** build; board-test: a seed-specific board experiment; experiment: a score-blind run. Only builds count as a build. */
  kind?: "build" | "board-test" | "experiment";
  complete: boolean;
  score: number | null;
  done_reports: number | null;
  done_credited: number | null;
  declines_credited: number | null;
  declines_not_credited: number | null;
  /** What each "done" rested on (scripts/ledger.py, the same rule as `doneBasis` in conduct.ts); absent in older files. */
  done_after_rise?: number | null;
  done_own?: number | null;
  done_own_credited?: number | null;
  done_room_check?: number | null;
  done_room_check_credited?: number | null;
  done_spill?: number | null;
  done_spill_credited?: number | null;
  /** Score-blind nights: the agent's own checks, and how many said "not done" (scripts/ledger.py). */
  blind_checks?: number | null;
  blind_said_no?: number | null;
};

export const LEDGER_NIGHTS: readonly LedgerNight[] = data.nights as LedgerNight[];

/** Every live start the ledger read (nights with no log included), and the newest start time, ISO. */
export const LEDGER_META: { liveStarts: number | null; latestStart: string | null } = {
  liveStarts: typeof (data as { live_starts?: unknown }).live_starts === "number" ? (data as { live_starts: number }).live_starts : null,
  latestStart: typeof (data as { latest_start?: unknown }).latest_start === "string" ? (data as { latest_start: string }).latest_start : null,
};

/**
 * The final branch's own-judgement "done" counted once per (seed, request), not once per replay of the same
 * deterministic seed (jury round 5, the data juror), with a Wilson 95 % interval; null in an older file.
 */
export type DistinctClaims = { scope: string; nights: number; reports: number; claims: number; credited: number; ci95: [number, number]; missed: string[] };

export const DISTINCT_OWN: DistinctClaims | null = (() => {
  const value = (data as unknown as { distinct_own?: Partial<DistinctClaims> }).distinct_own;
  return value && typeof value.claims === "number" && typeof value.credited === "number" && Array.isArray(value.ci95) ? (value as DistinctClaims) : null;
})();

/** The Wilson score interval (95 %) for `successes` of `n`: honest at small n and at 100 % (scripts/ledger.py `wilson`). */
export function wilson(successes: number, n: number, z = 1.959964): [number, number] {
  if (n === 0) return [0, 1];
  const p = successes / n;
  const denom = 1 + (z * z) / n;
  const centre = (p + (z * z) / (2 * n)) / denom;
  const half = (z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n))) / denom;
  return [Math.max(0, centre - half), Math.min(1, centre + half)];
}

/** "70–100 %", "92–99,7 %": whole per cent, a decimal where a whole number would round a miss up to 100 %. */
export function intervalText([low, high]: readonly [number, number], successes: number, n: number): string {
  const top = high * 100;
  const upper = successes < n && Math.round(top) >= 100 ? (Math.round(top * 10) / 10).toLocaleString("nb-NO", { maximumFractionDigits: 1 }) : String(Math.round(top));
  return `${Math.round(low * 100)}–${upper} %`;
}

/** The score-blind nights' own checks: how many there were and how many said "not done"; null when none were logged. */
export function blindChecks(nights: readonly LedgerNight[] = LEDGER_NIGHTS): { checks: number; saidNo: number } | null {
  const blind = nights.filter((night) => night.kind === "experiment" && typeof night.blind_checks === "number");
  if (blind.length === 0) return null;
  return { checks: blind.reduce((sum, night) => sum + (night.blind_checks ?? 0), 0), saidNo: blind.reduce((sum, night) => sum + (night.blind_said_no ?? 0), 0) };
}

export type Precision = {
  nights: number;
  reported: number;
  credited: number;
  /** One decimal; never rounds up to 100 while one "done" was not credited. */
  percent: number;
};

/** Credited "done" over reported "done" for `nights`; null when none of them reported a "done". */
export function precision(nights: readonly LedgerNight[]): Precision | null {
  const counted = nights.filter((night) => (night.done_reports ?? 0) > 0);
  const reported = counted.reduce((sum, night) => sum + (night.done_reports ?? 0), 0);
  const credited = counted.reduce((sum, night) => sum + (night.done_credited ?? 0), 0);
  if (reported === 0) return null;
  let percent = Math.round((credited / reported) * 1000) / 10;
  if (credited < reported) percent = Math.min(percent, 99.9);
  return { nights: counted.length, reported, credited, percent };
}

export type OwnPrecision = Precision & { roomChecks: { reported: number; credited: number } };

/**
 * The "done" the robot said on its own judgement (no score rise during the task) over `nights`: credited
 * over reported, and the room checks among them; null when no night has the split or none was said.
 */
export function ownPrecision(nights: readonly LedgerNight[]): OwnPrecision | null {
  const counted = nights.filter((night) => (night.done_own ?? 0) > 0);
  const reported = counted.reduce((sum, night) => sum + (night.done_own ?? 0), 0);
  const credited = counted.reduce((sum, night) => sum + (night.done_own_credited ?? 0), 0);
  if (reported === 0) return null;
  let percent = Math.round((credited / reported) * 1000) / 10;
  if (credited < reported) percent = Math.min(percent, 99.9);
  const roomChecks = {
    reported: counted.reduce((sum, night) => sum + (night.done_room_check ?? 0), 0),
    credited: counted.reduce((sum, night) => sum + (night.done_room_check_credited ?? 0), 0),
  };
  return { nights: counted.length, reported, credited, percent, roomChecks };
}

/** The shift id on the log's `start` line. */
export function shiftOf(lines: readonly RunLine[]): string | null {
  const start = lines.find((line) => line.type === "start");
  return start?.type === "start" ? start.shift : null;
}

export type CrossNight = {
  /** Every live night in the ledger. */
  all: Precision | null;
  /** The build nights played by the same commit as the night on screen (board tests left out); null when the ledger does not know it. */
  build: (Precision & { commit: string }) | null;
  /** The same two, counting only the "done" said on the robot's own judgement. */
  allOwn?: OwnPrecision | null;
  buildOwn?: OwnPrecision | null;
  /** The score-blind runs (kind=experiment): the agent never read the score or the reply when it said "done". */
  blind?: Precision | null;
};

/** The whole ledger, and the build that played `shift`. */
export function crossNightPrecision(shift: string | null, nights: readonly LedgerNight[] = LEDGER_NIGHTS): CrossNight {
  const all = precision(nights);
  const builds = nights.filter((night) => night.kind === undefined || night.kind === "build");
  const commit = shift ? builds.find((night) => night.shift === shift)?.commit : undefined;
  const sameNights = commit ? builds.filter((night) => night.commit === commit) : [];
  const same = commit ? precision(sameNights) : null;
  return {
    all,
    build: same && commit ? { ...same, commit } : null,
    allOwn: ownPrecision(nights),
    buildOwn: commit ? ownPrecision(sameNights) : null,
    blind: precision(nights.filter((night) => night.kind === "experiment")),
  };
}

/** "4 340" (a thin non-breaking space, as Norwegian figures are grouped). */
export function grouped(n: number): string {
  return n.toLocaleString("nb-NO").replace(/\s/g, " ");
}

/** "99,2 %". */
export function percentText(percent: number): string {
  return `${percent.toLocaleString("nb-NO", { minimumFractionDigits: 1, maximumFractionDigits: 1 })} %`;
}

/** One fault rate of the offline fault bed: the done check's precision and recall, blind and sighted. */
export type FaultRate = {
  rate: number;
  blind: { precision: number; recall: number };
  sighted: { precision: number; recall: number };
  /** Blind precision on the faults the reply it reads can show. */
  visible: { precision: number };
  /** How often the blind check said "not done". */
  saidNotDone: number;
};

/** The fault bed (data/fault-bed.json, hamad/faults): failures injected at known rates, offline. */
export const FAULT_BED: {
  branch: string;
  commit: string;
  nights: number;
  realNights: number;
  draws: number;
  faultTypes: number;
  rates: FaultRate[];
  saidNotDoneWithoutFaults: number;
  visibleCaught: string;
  sightedSignsFalseDone: number;
  lookAlikeMissed: number;
} = faults;

/** "98,5 %", "91 %": a share as Norwegian per cent, a decimal only where it says something. */
export function shareText(share: number): string {
  const percent = Math.round(share * 1000) / 10;
  return `${percent.toLocaleString("nb-NO", { maximumFractionDigits: 1 })} %`;
}
